    CTCPerceiveThing* perceive;
    C3DVector         position;
    CThingAICreature() : perceive(0), position(0.0f, 0.0f, 0.0f) { for (int i = 0; i < 9; ++i) presentBits[i] = 0; }
    bool HasTC(long type) const { return (presentBits[type >> 5] & (1u << (type & 31))) != 0; }
