    {
        if (HasTC(0x34)) {
            float radius = Min(GetPerceiveTC()->GetSightRadius(), event.SightRadius);
            if ((GetPosition() - event.Pos).GetLengthSquared() < radius * radius)
                return true;
        }
        return false;
    }
};

